package coder
import("os";"path/filepath";"runtime";"strings";"testing")
func TestCoderEngine(t *testing.T){e:=NewEngine();items,err:=e.ListDirectory(".");if err!=nil{t.Fatal(err)};if len(items)==0{t.Error("Expected files in current directory")};fn,code:=e.GenerateCode("create an http server api","go");if fn!="server.go"||code==""{t.Errorf("Failed to generate code: %s",fn)};tempFile:=filepath.Join(t.TempDir(),"swypik_test_file.txt");defer os.Remove(tempFile);if err:=e.CreateFile(tempFile,"SwypikOS Native File Content");err!=nil{t.Fatal(err)};content,err:=e.ReadFile(tempFile);if err!=nil{t.Fatal(err)};if content!="SwypikOS Native File Content"{t.Error(content)};res:=e.ExecuteCommand("echo SwypikOS Native Execution");if runtime.GOOS!="windows"{if res.Success||!strings.Contains(res.Output,"requires Windows"){t.Fatal("legacy Windows shell must not execute on Linux")};return};if !res.Success||res.Output!="SwypikOS Native Execution"{t.Errorf("Command execution failed: %v, output: %s",res.Success,res.Output)}}
